export declare const CSS = "\n:host{all:initial}\n*{box-sizing:border-box;font-family:-apple-system,\"Hiragino Sans\",\"Noto Sans JP\",sans-serif;-webkit-touch-callout:none}\n.root,.menu,.panel,.sheet,.toast{pointer-events:auto}\n.root{position:fixed;inset:0;z-index:1;background:#fff;overflow:hidden;touch-action:none;user-select:none;-webkit-user-select:none}\n.root{transition:transform .2s ease-out}\n.root img{position:absolute;left:0;top:0;pointer-events:none}\n.busy{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:#111;background:rgba(255,255,255,.8);font-size:16px}\nbutton{font-size:14px;padding:8px 12px;border:1px solid #cbd5e1;border-radius:8px;background:#fff;color:#111;cursor:pointer}\nbutton:disabled{opacity:.5}\nbutton.primary{background:#2563eb;color:#fff;border-color:#2563eb}\nbutton.danger{color:#e11d48;border-color:#e11d48}\n.menu{position:fixed;display:flex;gap:6px;align-items:center;padding:6px;background:rgba(255,255,255,.96);border:1px solid #cbd5e1;border-radius:12px;box-shadow:0 2px 10px rgba(0,0,0,.25);z-index:3}\n.grip{padding:6px 8px;color:#64748b;cursor:grab;font-size:18px;user-select:none}\n.panel{position:fixed;z-index:3;display:flex;flex-direction:column;background:#fff;border:1px solid #cbd5e1;border-radius:12px;box-shadow:0 4px 16px rgba(0,0,0,.3);padding:10px;color:#111;font-size:14px}\n.panel[hidden]{display:none}\n.list{overscroll-behavior:contain;overflow:auto;flex:1;min-height:40px}\n.path{color:#64748b;font-size:12px;margin-top:6px}\n.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;font-weight:bold}\n.head button{font-size:12px;padding:4px 8px}\n.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}\n.thumb{position:relative;border:2px solid #cbd5e1;border-radius:8px;overflow:hidden;background:#f1f5f9;cursor:pointer}\n.thumb.cur{border-color:#2563eb}\n.thumb .pic{position:relative;height:150px;display:block}\n.thumb img,.thumb svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}\n.thumb img{object-fit:cover;object-position:top}\n.thumb .cap{padding:3px 6px;font-size:11px;color:#334155;background:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.thumb .x{position:absolute;top:2px;right:2px;width:26px;height:26px;padding:0;border-radius:50%;border:none;background:rgba(15,23,42,.75);color:#fff;font-size:14px;line-height:26px}\n.status{margin-top:6px;font-size:13px;color:#111}\na.btn{display:inline-block;margin-top:6px;padding:8px 12px;border-radius:8px;background:#2563eb;color:#fff;text-decoration:none;font-size:14px}\n.empty,.note{color:#64748b;font-size:12px;padding:6px 0}\n.row{display:flex;gap:8px;margin-top:8px;flex-wrap:wrap}\n.sheet{position:fixed;z-index:4;display:flex;gap:6px;align-items:flex-start;background:#fff;border:1px solid #cbd5e1;border-radius:12px;box-shadow:0 4px 16px rgba(0,0,0,.35);padding:6px}\n.sheet .del{flex:none;padding:6px 8px;font-size:16px;line-height:1.4;border-color:#e11d48}\n.sheet textarea{flex:1;min-width:0;overscroll-behavior:contain;font-size:16px;padding:6px;border:1px solid #cbd5e1;border-radius:8px;resize:none;color:#111;background:#fff;display:block;line-height:1.4;min-height:calc(1.4em + 14px);overflow:hidden}\n.toast{position:fixed;left:50%;top:60px;transform:translateX(-50%);background:#111;color:#fff;padding:8px 14px;border-radius:8px;font-size:14px;z-index:5}\n";
export declare const LAUNCHER_CSS = "\n:host{all:initial}\n*{box-sizing:border-box;font-family:-apple-system,\"Hiragino Sans\",\"Noto Sans JP\",sans-serif}\n.wrap{position:fixed;width:44px;height:44px;z-index:2147483646}\n.btn{position:absolute;inset:0;width:44px;height:44px;padding:0;border:1px solid rgba(255,255,255,.7);border-radius:50%;background:rgba(37,99,235,.55);color:#fff;font-size:20px;line-height:1;cursor:pointer;touch-action:none;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none;box-shadow:0 2px 8px rgba(0,0,0,.3)}\n.btn:hover{background:rgba(37,99,235,.85)}\n.badge{position:absolute;top:-6px;right:-6px;min-width:18px;height:18px;padding:0 4px;border-radius:9px;background:#e11d48;color:#fff;font-size:11px;line-height:18px;text-align:center;pointer-events:none}\n.badge[hidden]{display:none}\n.close{position:absolute;top:-16px;left:-16px;width:18px;height:18px;padding:0;border:none;border-radius:50%;background:rgba(15,23,42,.7);color:#fff;font-size:12px;line-height:18px;cursor:pointer}\n.btn:focus-visible{outline:3px solid #fff;outline-offset:2px;box-shadow:0 0 0 5px #2563eb}\n.btn.busy{pointer-events:none;color:transparent}\n.btn.busy::after{content:\"\";position:absolute;left:50%;top:50%;width:20px;height:20px;margin:-10px 0 0 -10px;border:3px solid rgba(255,255,255,.4);border-top-color:#fff;border-radius:50%;animation:spin .8s linear infinite}\n@keyframes spin{to{transform:rotate(360deg)}}\n";
